/**
 * Skills over MCP (`io.modelcontextprotocol/skills`, SEP-2640). Serves the
 * reader and listing skills to connected clients, so a connector user gets the
 * same playbooks the Claude Code plugin ships, with nothing to install.
 *
 * The files are embedded at build time (`src/skill-bundles.ts`, regenerated by
 * `bun run mcp:skills:build`). The catalog is built once per isolate and
 * attached to every per-request server; it is the same for every caller, so
 * its cache hint is `public`.
 */
import type { McpServer } from "@modelcontextprotocol/server";
import {
  SkillsExtension,
  memorySkillFiles,
  type SkillCatalog,
} from "@modelcontextprotocol/server/ext/skills";
import { SKILL_FILES } from "./skill-bundles.js";

const SKILLS_CACHE_HINT = { ttlMs: 3_600_000, cacheScope: "public" } as const;

let catalog: Promise<SkillCatalog> | undefined;

export function loadSkillsCatalog(
  files: Record<string, string> = SKILL_FILES,
): Promise<SkillCatalog> {
  return SkillsExtension.load(memorySkillFiles(files), {
    cacheHint: SKILLS_CACHE_HINT,
    strict: true,
  });
}

/** Attach the shared skills catalog to `server`. Must run before the server connects. */
export async function registerSkills(server: McpServer): Promise<void> {
  catalog ??= loadSkillsCatalog().catch((err) => {
    catalog = undefined;
    throw err;
  });
  (await catalog).attach(server);
}
